"""Emit Gowin pROM banks with explicit, independently verifiable initialization."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def emit(name,width,address_width,values):
    words=16384//width
    low=words.bit_length()-1
    shift=width.bit_length()-1
    # Trailing all-zero banks are represented by the mux default, not hardware.
    end=len(values)
    while end>1 and values[end-1]==0:end-=1
    banks=(end+words-1)//words
    lines=['`timescale 1ns/1ps',
           '// Generated by tools/pack_artwork.py; one synchronous read cycle.',
           f'module {name}(input wire clk,input wire [{address_width-1}:0] addr,',
           f' output reg [{width-1}:0] data);']
    if address_width>low:
        lines += [f'reg [{address_width-low-1}:0] bank;',
                  f'always @(posedge clk) bank<=addr[{address_width-1}:{low}];']
    for b in range(banks):
        block=values[b*words:(b+1)*words]
        block+= [0]*(words-len(block))
        bits=sum(v<<(i*width) for i,v in enumerate(block))
        lines += [f'wire [31:0] q{b};',
                  f'pROM #(.READ_MODE(1\'b0),.BIT_WIDTH({width}),.RESET_MODE("SYNC"),']
        for k in range(64):
            init=(bits>>(k*256))&((1<<256)-1)
            lines += [f" .INIT_RAM_{k:02X}(256'h{init:064x})"+(',' if k<63 else '')]
        lines += [f") rom{b}(.DO(q{b}),.AD({{addr[{low-1}:0],{shift}'b0}}),",
                  " .CLK(clk),.CE(1'b1),.OCE(1'b1),.RESET(1'b0));"]
    if address_width>low:
        lines+=['always @* begin',' case(bank)']
        for b in range(banks):lines += [f" {address_width-low}'d{b}:data=q{b}[{width-1}:0];"]
        lines+=[' default:data=0;',' endcase','end']
    else:lines += [f'always @* data=q0[{width-1}:0];']
    lines+=['endmodule','']
    (ROOT/'src'/f'{name}.v').write_text('\n'.join(lines),encoding='ascii')
    return banks
